questions.referenceAnswer:
class Animal {
    private String name;
    public Animal(String name) { this.name = name; }
    public String speak() { return "..."; }
}

class Dog extends Animal {
    public Dog(String name) { super(name); }
    @Override
    public String speak() { return "汪汪"; }
}
